CREATE OR REPLACE FUNCTION public._pgtrigger_should_ignore(trigger_name name)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
                DECLARE
                    _pgtrigger_ignore TEXT[];
                    _result BOOLEAN;
                BEGIN
                    BEGIN
                        SELECT INTO _pgtrigger_ignore
                            CURRENT_SETTING('pgtrigger.ignore');
                        EXCEPTION WHEN OTHERS THEN
                    END;
                    IF _pgtrigger_ignore IS NOT NULL THEN
                        SELECT trigger_name = ANY(_pgtrigger_ignore)
                        INTO _result;
                        RETURN _result;
                    ELSE
                        RETURN FALSE;
                    END IF;
                END;
            $function$

public.pgtrigger_notify_enqueueing_0bc94.definition:
CREATE OR REPLACE FUNCTION public.pgtrigger_notify_enqueueing_0bc94()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$

                BEGIN
                    IF ("public"._pgtrigger_should_ignore(TG_NAME) IS TRUE) THEN
                        IF (TG_OP = 'DELETE') THEN
                            RETURN OLD;
                        ELSE
                            RETURN NEW;
                        END IF;
                    END IF;

                    PERFORM pg_notify(
                        'authentik.tasks.' || NEW.queue_name || '.enqueue',
                        NEW.message_id::text
                    );
                    RETURN NEW;

                END;
            $function$

public.pgtrigger_notify_new_channels_mes.definition:
CREATE OR REPLACE FUNCTION public.pgtrigger_notify_new_channels_message_d21ae()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
                DECLARE payload text; encoded_message text; epoch text;
                BEGIN
                    IF ("public"._pgtrigger_should_ignore(TG_NAME) IS TRUE) THEN
                        IF (TG_OP = 'DELETE') THEN
                            RETURN OLD;
                        ELSE
                            RETURN NEW;
                        END IF;
                    END IF;

                    encoded_message := encode(NEW.message, 'base64');
                    epoch := extract(epoch from NEW.expires)::text;
                    IF octet_length(NEW.id::text) + octet_length(NEW.channel) + octet_length(epoch) + octet_length(encoded_message) + 3 < 8000 THEN
                        payload := NEW.id::text || ':' || NEW.channel || ':' || epoch || ':' || encoded_message;
                    ELSE
                        payload := NEW.id::text || ':' || NEW.channel || ':' || epoch;
                    END IF;

                    PERFORM pg_notify('channels_messages', payload);
                    RETURN NEW;

                END;
            $function$

